/* ============================================================
   أطياب الجاسم (React) — اختيار طريقة الدفع (MethodPicker)

   قائمة منسدلة واحدة (Drop list) بدل صفّ البطاقات الطويل: العميل
   يفتح القائمة فيرى كل الطرق مرّة واحدة، والمختارة تظهر باسمها
   وأيقونتها، وتحتها سطر واحد يشرح كيف تتم فعلاً.

   ★ الطرق من الخادم (storeInfo.payments — تُجلب مرة واحدة وتُحفظ)،
     والاحتياط الثابت PAY_METHODS لا يُستعمل إلا قبل وصول الرد أو عند
     فشله — فلا تتكرّر خيارات الدفع في مكانين.
   ★ الدفع عند الاستلام يُحجب تلقائياً إن عطّله المتجر
     (cashOnDeliveryEnabled=false).
   ★ كومبوننت واحد تستعمله العربة (Payment) وصفحة إتمام الدفع.
   ============================================================ */

import { useEffect } from "react";
import { PAY_METHODS } from "../../redux/slices/cartSlice.js";
import { loadStoreSection, feeText } from "../../redux/slices/storeInfoSlice.js";
import { selectStoreSettings } from "../../redux/slices/settingsSlice.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { PAY_ICON, PAY_HINT, PAY_CARDS } from "../../constants/payment.js";
import { T } from "../../i18n.js";
import { Icon } from "./Icons.jsx";

/* السطر الأول في PAY_METHODS مفتاحه فارغ — هو نصّ «اختر…» نفسه */
function placeholderOf(language) {
  let text = "— اختر طريقة الدفع —";
  PAY_METHODS.forEach(function (m) {
    if (!m.key) text = language === "en" ? m.en || m.label : m.label;
  });
  return text;
}

function labelOf(m, language) {
  if (!m) return "";
  if (m.label) return language === "en" ? m.en || m.label : m.label;
  return language === "en" ? m.en || m.name : m.name || m.en || "";
}

export default function MethodPicker(props) {
  const dispatch = useAppDispatch();
  const value = props.value || "";
  const name = props.name || "atyab-pay";
  const id = props.id || name + "-select";
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const live = useAppSelector(function (s) {
    return s.storeInfo.payments;
  });
  const settings = useAppSelector(selectStoreSettings);

  /* ★ الدفع عند الاستلام هو الوحيد الفعّال: يُختار تلقائيًا ما لم يختر العميل */
  useEffect(
    function () {
      if (!value && methods.some(function (m) { return m.key === "cod"; })) {
        props.onChange("cod");
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [methods.length, value]
  );

  /* ★ الجلب مرة واحدة — الشريحة تتذكّر ما وصل (CACHE-HIT) */
  useEffect(
    function () {
      dispatch(loadStoreSection("payments"));
    },
    [dispatch]
  );

  const fetched = live && Array.isArray(live.items) ? live.items : [];
  const base = fetched.length
    ? fetched.map(function (m) {
        return { key: m.key, label: m.name, en: m.en, fee: Number(m.fee) || 0, feeType: m.feeType || "" };
      })
    : PAY_METHODS.filter(function (m) {
        return !!m.key;
      });
  /* ★ حجب الدفع عند الاستلام إن عطّله المتجر */
  const methods = settings && settings.cashOnDeliveryEnabled === false
    ? base.filter(function (m) {
        return m.key !== "cod";
      })
    : base;

  /* ★ الشرح للمستخدم من الكتالوج + رسوم الطريقة المختارة (كانت
     «لا تُعرض أبداً» — الآن تُعرض لأن المالك يريدها في الفاتورة) */
  let hint = value && PAY_HINT[value] ? T(PAY_HINT[value], language) : "";
  if (!hint && PAY_CARDS[value]) hint = T(PAY_CARDS[value].desc, language);
  if (!hint && fetched.length) {
    for (let i = 0; i < fetched.length; i++) {
      if (fetched[i].key === value && fetched[i].desc) {
        hint = T(fetched[i].desc, language);
        break;
      }
    }
  }
  /* ★ رسوم المختارة من الخادم (fee/feeType) تُلحق بالشرح */
  let feeHint = "";
  for (let i = 0; i < fetched.length; i++) {
    if (fetched[i].key === value && Number(fetched[i].fee) > 0) {
      const ft = feeText(fetched[i]);
      feeHint = language === "en" ? ft.en : ft.ar;
      break;
    }
  }

  return (
    <div className={"ct-pay-select" + (props.className ? " " + props.className : "")}>
      <div className={"ct-select-wrap" + (value ? " is-set" : "")}>
        <span className="ct-select-ic" aria-hidden="true">
          <Icon name={PAY_ICON[value] || "card"} strokeWidth={1.7} />
        </span>

        <select
          className="ct-select"
          id={id}
          name={name}
          value={value}
          aria-label="طريقة الدفع"
          onChange={function (e) {
            props.onChange(e.target.value);
          }}
        >
          <option value="">{placeholderOf(language)}</option>
          {methods.map(function (m) {
            var soon = m.key !== "cod";
            return (
              <option key={m.key} value={m.key} disabled={soon}>
                {labelOf(m, language) + (soon ? (language === "en" ? " — Soon" : " — قريبًا") : "")}
              </option>
            );
          })}
        </select>

        <span className="ct-select-arrow" aria-hidden="true">
          <Icon name="chev" strokeWidth={2.2} />
        </span>
      </div>

      {hint || feeHint ? (
        <p className="ct-select-hint">
          {hint}
          {hint && feeHint ? " · " : ""}
          {feeHint ? <b>{feeHint}</b> : null}
        </p>
      ) : null}
    </div>
  );
}
