/* ============================================================
   أطياب الجاسم (React) — كوبون الخصم (CouponBox)

   مربع الكوبون: الحقل + زر «طبّق» + الكوبون المُطبَّق (مع زر إزالته)
   + رسالة الكوبون + أكواد تجريبية جاهزة للضغط.
   كومبوننت واحد تستعمله العربة (Payment) وصفحة إتمام الدفع — فالكوبون
   نفسه يُدار من مكان واحد ويُحسَب في selectors.

   ★ الكود يُكتب بحروف كبيرة، ويُخزَّن في Redux (cartSlice).
   ★ id قابل للتغيير كي لا يتكرّر معرّف الحقل في صفحتين في وقت واحد.
   ============================================================ */

import { useEffect, useState } from "react";
import { COUPONS, applyCouponCode, removeCouponCode } from "../../redux/slices/cartSlice.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { selectCartTotals } from "../../redux/selectors.js";
import { Icon } from "./Icons.jsx";

export default function CouponBox(props) {
  const dispatch = useAppDispatch();
  const totals = useAppSelector(selectCartTotals);
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const couponMsg = useAppSelector(function (s) {
    return s.cart.couponMsg;
  });
  const couponBusy = useAppSelector(function (s) {
    return !!s.cart.couponBusy;
  });
  const appliedCode = useAppSelector(function (s) {
    return s.cart.coupon || "";
  });
  const snapshotNet = useAppSelector(function (s) {
    return s.cart.couponInfo ? s.cart.couponInfo.snapshotNet : null;
  });
  const [code, setCode] = useState("");
  const inputId = props.id || "ctCouponInput";

  /* ★ تغيّرت العربة بعد التحقق؟ نُعيد التحقق بصمت — فالشرط (مثل فوق 300)
     قد يسقط، فيسقط الكوبون مع تنبيه بدل خصمٍ كاذب */
  useEffect(
    function () {
      if (!appliedCode) return;
      if (snapshotNet == null || Number(snapshotNet) === Number(totals.net)) return;
      dispatch(applyCouponCode(appliedCode, { silent: true }));
    },
    [dispatch, appliedCode, snapshotNet, totals.net]
  );

  return (
    <div className={"ct-card ct-coupon" + (props.className ? " " + props.className : "")}>
      <h3>
        <Icon name="tag" strokeWidth={1.8} />
        <span>كوبون الخصم</span>
      </h3>
      <p className="ct-coupon-sub">أدخل كود الخصم ثم اضغط «طبّق».</p>

      <div className="ct-coupon-form">
        <input
          className="ct-input"
          id={inputId}
          type="text"
          autoComplete="off"
          spellCheck="false"
          placeholder="اكتب الكود هنا"
          aria-label="كود الخصم"
          value={code}
          onChange={function (e) {
            setCode(e.target.value.toUpperCase());
          }}
          onKeyDown={function (e) {
            if (e.key === "Enter") {
              e.preventDefault();
              dispatch(applyCouponCode(code));
            }
            if (e.key === "Escape") setCode("");
          }}
        />
        <button
          className="ct-apply"
          type="button"
          disabled={couponBusy}
          onClick={function () {
            dispatch(applyCouponCode(code));
          }}
        >
          {couponBusy ? "…" : "طبّق"}
        </button>
      </div>

      {totals.coupon ? (
        <div className="ct-applied">
          <Icon name="check" strokeWidth={2.1} />
          <span>
            <b>{totals.code}</b>
            {language === "en" ? totals.coupon.labelEn || totals.coupon.label : totals.coupon.label}
          </span>
          <button
            type="button"
            aria-label="إزالة الكوبون"
            title="إزالة الكوبون"
            onClick={function () {
              dispatch(removeCouponCode());
              setCode("");
            }}
          >
            ×
          </button>
        </div>
      ) : null}

      {couponMsg && couponMsg.text ? (
        <p className={"ct-coupon-msg is-" + couponMsg.tone}>
          {language === "en" ? couponMsg.textEn || couponMsg.text : couponMsg.text}
        </p>
      ) : null}

      {Object.keys(COUPONS).length ? (
        <p className="ct-coupon-hint">
          أكواد تجريبية للتجربة:{" "}
          {Object.keys(COUPONS).map(function (key) {
            return (
              <button
                key={key}
                type="button"
                className="ct-code"
                onClick={function () {
                  setCode(key);
                  dispatch(applyCouponCode(key));
                }}
              >
                {key}
              </button>
            );
          })}
        </p>
      ) : null}
    </div>
  );
}
