/* تاريخ مقروء بدون أي اعتماد على تنسيق المتصفّح (يوم/شهر/سنة · ساعة:دقيقة) */
function shortDate(ms) {
  const d = new Date(ms);
  return pad2(d.getDate()) + "/" + pad2(d.getMonth() + 1) + "/" + d.getFullYear();
}
function shortTime(ms) {
  const d = new Date(ms);
  return pad2(d.getHours()) + ":" + pad2(d.getMinutes());
}

/* اسم طريقة الدفع بلغة الواجهة — من مفتاح الطريقة المحفوظ في الطلب،
   وإلا من الاسم المُجمَّد في الطلبات القديمة. */
function methodText(order, language) {
  return methodLabelOf(order && order.method, language) || T(order && order.methodLabel, language);
}

/* حقول النموذج تُبنى من الملف الشخصي إن وُجد — فلا يُعيد العميل كتابتها.
   ★ البريد معروف من الحساب فلا نطلبه هنا — مكانه قائمة الدولة (افتراضي AE).
   ★ الموافقة مفعّلة مسبقاً كما طُلب. */
function initialForm(profile) {
  const a = (profile && profile.address) || {};
  return {
    firstName: (profile && profile.firstName) || "",
    lastName: (profile && profile.lastName) || "",
    phone: (profile && profile.phone) || "",
    region: (profile && profile.region) || "AE",
    city: a.city || "",
    district: a.district || "",
    street: a.street || "",
    building: a.building || "",
    postal: a.postal || "",
    propertyType: a.propertyType || "",
    notes: a.notes || "",
    method: "",
    ship: "",
    transferAck: false,
    agree: true
  };
}

/* اسم الدولة بلغة الواجهة */
function countryName(key, language) {
  const c = countryByKey(key);
  if (!c) return key || "";
  return language === "en" ? c.labelEn || c.label : c.label;
}

/* ------------------------------------------------------------
   حقل واحد: عنوان + خانة + رسالة خطأ تحته (نصّ أو قائمة منسدلة)
   ------------------------------------------------------------ */
function Field(props) {
  const bad = !!props.error;
  return (
    <div className={"ck-field" + (props.wide ? " is-wide" : "") + (bad ? " is-bad" : "")}>
      <label className="ck-label" htmlFor={props.id}>
        <span>{props.label}</span>
        {props.required ? <em className="ck-req">مطلوب</em> : <em className="ck-opt">اختياري</em>}
      </label>
      {props.tag === "select" ? (
        props.loading ? (
          <span className="sk-block sk-field" role="status" aria-label="جارٍ تحميل القائمة" />
        ) : (
        <select
          className="ct-input ck-input ck-select"
          id={props.id}
          name={props.id}
          value={props.value || ""}
          onChange={function (e) {
            props.onChange(e.target.value);
          }}
          onBlur={props.onBlur}
        >
          {props.placeholder ? <option value="">{props.placeholder}</option> : null}
          {(props.options || []).map(function (opt) {
            return (
              <option key={opt.key} value={opt.key}>
                {opt.label}
              </option>
            );
          })}
        </select>
        )
      ) : (
        <input
          className="ct-input ck-input"
          id={props.id}
          name={props.id}
          type={props.type || "text"}
          value={props.value}
          placeholder={props.placeholder || ""}
          autoComplete={props.autoComplete || "off"}
          inputMode={props.inputMode}
          maxLength={props.maxLength}
          dir={props.dir}
          onChange={function (e) {
            props.onChange(e.target.value);
          }}
          onBlur={props.onBlur}
        />
      )}
      {bad ? (
        <p className="ck-err">
          <Icon name="alert" strokeWidth={2} />
          <span>{props.error}</span>
        </p>
      ) : props.hint ? (
        <p className="ck-hint">{props.hint}</p>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------
   شريط الخطوات — نقرة على خطوة سابقة ترجع إليها بعد التحقّق
   ------------------------------------------------------------ */
function StepRail(props) {
  const list = props.steps || STEPS;
  const at = list.findIndex(function (s) { return s.key === props.step; });
  const cur = at === -1 ? 0 : at;
  return (
    <ol className="ck-steps">
      {list.map(function (s, i) {
        const state = i < cur ? "is-done" : i === cur ? "is-on" : "is-off";
        return (
          <li key={s.key} className={"ck-step " + state}>
            <button type="button" disabled={i > cur} onClick={function () { props.onJump(s.key); }}>
              <span className="ck-step-n">
                {i < cur ? <Icon name="check" strokeWidth={2.6} /> : i + 1}
              </span>
              <span className="ck-step-tx">
                <b>{s.label}</b>
                <small>{s.hint}</small>
              </span>
            </button>
          </li>
        );
      })}
    </ol>
  );
}

